using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Generic;using UnityEngine;
public class BatchThreeSwitchSave:MonoBehaviour {
 IEnumerator Start(){DontDestroyOnLoad(gameObject);ConnectionManager.Instance.DisconnectFromServer();yield return new WaitForSeconds(6);var server=new GameServerInfo();server.SetValue(GameInfoString.IP,"127.0.0.1");server.SetValue(GameInfoInt.Port,27980);ServerInfoCache.Instance.SavePassword(server,"delve-local-test");ConnectionManager.Instance.LastJoinSource="Batch 3 copied save visual check";ConnectionManager.Instance.Connect(server);Destroy(gameObject);}
}
public class BatchThreeWorldAcceptance:MonoBehaviour {
 StringBuilder log=new StringBuilder();EntityPlayerLocal p;World world;
 void Check(bool ok,string text){if(!ok)throw new Exception(text);log.AppendLine("PASS "+text);}
 void Capture(string name){Type.GetType("UnityEngine.ScreenCapture, UnityEngine.ScreenCaptureModule").GetMethod("CaptureScreenshot",new[]{typeof(string),typeof(int)}).Invoke(null,new object[]{Path.Combine(GameIO.GetUserGameDataDir(),"batch03-world-"+name+".png"),1});}
 IEnumerator Start(){var run=Run();while(true){bool more;object current=null;try{more=run.MoveNext();if(more)current=run.Current;}catch(Exception e){log.AppendLine("FAIL "+e);break;}if(!more)break;yield return current;}File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-world-acceptance.txt"),log.ToString());Destroy(gameObject);}
 IEnumerator Run(){world=GameManager.Instance.World;p=world.GetPrimaryPlayer();p.PlayerUI.windowManager.Close("skills");p.PlayerUI.windowManager.Close("crafting");p.PlayerUI.windowManager.Close("spawnselection");p.PlayerUI.windowManager.ReEnableHUD();p.IsGodMode.Value=true;p.IsFlyMode.Value=true;
 p.TeleportToPosition(new Vector3(-2681,75,-2193),false,new Vector3(-15,0,0));yield return new WaitForSeconds(10);p.SetRotation(new Vector3(-15,0,0));Capture("front");yield return new WaitForSeconds(1);
 Check(world.GetBlock(-2708,65,-2172).Block.GetBlockName()=="woodLogPillar100","exposed log wall block retained");Check(world.GetBlock(-2681,65,-2179).isair,"front gate clearance");Check(world.GetBlock(-2681,65,-2126).isair,"rear gate clearance");
 p.TeleportToPosition(new Vector3(-2681,90,-2168),false,new Vector3(-48,0,0));yield return new WaitForSeconds(5);p.SetRotation(new Vector3(-48,0,0));Capture("roofs");yield return new WaitForSeconds(1);
 p.TeleportToPosition(new Vector3(-2681,70,-2116),false,new Vector3(-12,180,0));yield return new WaitForSeconds(5);p.SetRotation(new Vector3(-12,180,0));Capture("rear");yield return new WaitForSeconds(1);
 foreach(var pos in new[]{new Vector3i(-2702,65,-2144),new Vector3i(-2697,65,-2144),new Vector3i(-2666,65,-2144),new Vector3i(-2681,65,-2155)})Check(world.GetTileEntity(pos)!=null,"service tile entity at "+pos);
 p.TeleportToPosition(new Vector3(-2681,65,-2137),false,new Vector3(0,0,0));yield return new WaitForSeconds(5);Capture("hall");yield return new WaitForSeconds(1);
 int npcs=0;foreach(var e in world.EntityAlives)if(EntityClass.GetEntityClassName(e.entityClass)=="delveWayrestSteward")npcs++;Check(npcs==1,"exactly one Steward");
 int index=0;foreach(string name in new[]{"cntShoppingCartWhite","cntShoppingCartEmptyWhite","cntShoppingCartTippedWhite"}){int x=-2620+index*3,z=-2140,y=world.GetTerrainHeight(x,z)+1;var pos=new Vector3i(x,y,z);p.TeleportToPosition(new Vector3(x,y+1,z-3),false,new Vector3(-15,0,0));yield return new WaitForSeconds(3);y=world.GetTerrainHeight(x,z)+1;pos=new Vector3i(x,y,z);p.TeleportToPosition(new Vector3(x,y+.2f,z-3),false,new Vector3(-15,0,0));world.SetBlocksRPC(new List<BlockChangeInfo>{new BlockChangeInfo(new BlockValueRef(pos+new Vector3i(0,-1,0)),Block.GetBlockValue("terrForestGround",false),(sbyte)-127)});yield return new WaitForSeconds(1);var b=Block.GetBlockValue(name,false);world.SetBlocksRPC(new List<BlockChangeInfo>{new BlockChangeInfo(new BlockValueRef(pos),b,(sbyte)127)});yield return new WaitForSeconds(3);p.SetRotation(new Vector3(-15,0,0));Capture(name);yield return new WaitForSeconds(.5f);Check(world.GetBlock(pos).Block.GetBlockName()==name,name+" remains placed at "+pos+" actual="+world.GetBlock(pos).Block.GetBlockName());log.AppendLine("TE="+world.GetTileEntity(pos));var cmds=b.Block.GetBlockActivationCommands(world,b,pos,p);Check(cmds!=null&&cmds.Length>0,name+" offers loot action");Check(b.Block.OnBlockActivated(cmds[0].text,world,pos,b,p),name+" activation accepted");yield return new WaitForSeconds(8);Check(p.PlayerUI.windowManager.IsWindowOpen("looting"),name+" native loot window opens");Capture(name+"-loot");yield return new WaitForSeconds(.4f);p.PlayerUI.windowManager.Close("looting");index++;}
 log.AppendLine("PASS COMPLETE Wayrest gates, services, single Steward and three crate loot variants; native screenshots captured");}
}

